  ('f8e6ee06-eef7-4979-8069-78914ad1e954', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Heteroskedasticity', 'Diagnose and handle nonconstant error variance common in real economic data. Core emphasis: Heteroskedasticity, robust standard errors, weighted least squares, diagnostics, and implications for inference.', 4),
