  ('ac8f21e5-4afc-4b6c-a825-f96ed15110bd', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', '34a94ae3-1895-4184-9208-920e37a527b4', 'concept'::public.curated_course_node_type, 'Conditional variance', null, 0),
