  ('2b23bd32-c51c-49e0-ba0a-603b83ff6f93', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', 'f8e6ee06-eef7-4979-8069-78914ad1e954', 'subtopic'::public.curated_course_node_type, 'Consequences', 'OLS coefficients may remain unbiased while conventional standard errors fail.', 1),
  ('3e4111ad-26aa-4623-afa7-ff755ebd11dd', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', '2b23bd32-c51c-49e0-ba0a-603b83ff6f93', 'concept'::public.curated_course_node_type, 'Unbiasedness versus efficiency', null, 0),
