  ('238b873c-931b-42da-a4d3-6c1833974fa3', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', '77cf717d-31b8-4d8e-847a-05d5f6e8e13c', 'concept'::public.curated_course_node_type, 'HC estimators', null, 0),
