  ('c6c86b3e-b115-429e-8734-2466668b8d15', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Autocorrelation', 'Understand serial dependence in errors and why time ordering changes inference. Core emphasis: Serial correlation, Durbin-Watson intuition, Newey-West standard errors, dynamic models, and time-series residuals.', 5),
  ('fbd3e171-e426-4933-b9fe-1a8488812c63', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', 'c6c86b3e-b115-429e-8734-2466668b8d15', 'subtopic'::public.curated_course_node_type, 'Serial dependence', 'Errors can be correlated across time, especially in macro and finance data.', 0),
