  ('5ff8358b-49bc-415c-83c4-2f3f395a9726', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', 'c6c86b3e-b115-429e-8734-2466668b8d15', 'subtopic'::public.curated_course_node_type, 'Consequences for inference', 'Autocorrelation makes naive standard errors too optimistic or misleading.', 1),
