  ('493ee51d-08e2-43cf-9748-0e7ab2950a5d', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', '29955009-8127-4039-a7a1-bd2db8bbe95f', 'concept'::public.curated_course_node_type, 'Lagged dependent variables', null, 0),
