  ('8613203d-fa96-46ad-ae31-41b42a6e0b60', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Instrumental variables', 'Introduce IV as a strategy for causal estimation when regressors are endogenous. Core emphasis: Endogeneity, instruments, relevance, exclusion, two-stage least squares, weak instruments, and overidentification.', 6),
