  ('eef162bc-c037-40da-9244-da917e4471f3', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', '4a53fdd5-5a9f-4d44-a1f4-3a1800588dac', 'concept'::public.curated_course_node_type, 'Omitted variables', null, 0),
