  ('4178e617-67c9-4705-aa22-8c94dc0c5bfa', 'd6e7f8a9-0b1c-4d94-9e35-4f5a6b7c8d44', '8613203d-fa96-46ad-ae31-41b42a6e0b60', 'subtopic'::public.curated_course_node_type, 'Instrument validity', 'A good instrument must move treatment while affecting the outcome only through treatment.', 1),
