s and sensitivity", "children": [{"id": "347ded3f-7b16-4a58-a2ba-fed6828c18c1", "type": "concept", "title": "Alternative specifications"}, {"id": "6d736f6a-1e72-4509-8cab-93d30c7862e1", "type": "concept", "title": "Placebo tests"}, {"id": "fef05e09-574e-44c9-9091-d832a5fdef53", "type": "concept", "title": "Subsample checks"}], "description": "Students learn to pressure-test empirical claims."}, {"id": "9abc32fa-f04d-4120-9cc6-a9c79e2242ff", "type": "subtopic", "title": "Writing empirical results", "children": [{"id": "2a63324e-9665-47e8-939a-3dfe72e3a547", "type": "concept", "title": "Regression tables"}, {"id": "64cdb67c-1a06-4a17-bf58-0928c8d161aa", "type": "concept", "title": "Figures"}, {"id": "fe12de84-f4d6-4a46-9fb5-be1e4d4d11d7", "type": "concept", "title": "Research memo structure"}], "description": "Communication turns analysis into evidence."}]}], "dbBacked": true}$ecmtjson$::jsonb,
