set
  title = 'Econometrics',
  goal = 'Econometrics',
  summary = 'Econometrics is the empirical engine of economics: it teaches students how to turn economic questions, data, assumptions, and statistical models into credible evidence. A high-quality version must separate prediction from causal identification, emphasize diagnostics and robustness, and require reproducible research habits.',
  data = $ecmtjson${"slug": "econometrics", "title": "Econometrics", "description": "Econometrics is the empirical engine of economics: it teaches students how to turn economic questions, data, assumptions, and statistical models into credible evidence. A high-quality version must separate prediction from causal identification, emphasize diagnostics and robustness, and require reproducible research habits.", "topics": [{"id": "c496d4f9-d8a6-4e3a-b065-45b075b1435b", "type": "topic", "title": "The classical linear regression model", "description": "Establish the core statistical model economists use to relate outcomes, explanatory variables, assumptions, and uncertainty. Core emphasis: Population regression, sample regression, error terms, exogeneity, linearity, conditional expectations, and interpretation.", "children": [{"id": "ce6c277e-61aa-4a18-8e37-0a5d4dd50146", "type": "subtopic", "title": "Population and sample regression", "children": [{"id": "ca3e7890-cadf-42fb-8ff5-b51fcbe684f8", "type": "concept", "title": "Population regression function"}, {"id": "66daabef-4698-47cc-a504-2adb6e1d70d1", "type": "concept", "title": "Sample regression function"}, {"id": "c5b861ed-ed39-4d0f-9e93-91a761c5cc54", "type": "concept", "title": "Parameters versus estimates"}], "description": "Students distinguish the true economic relationship from the estimate obtained in data."}, {"id": "c47bbf85-e330-4065-b487-3f3e029a775b", "type": "subtopic", "title": "Error terms and exogeneity", "children": [{"id": "927bef83-d890-4e39-b370-f97dc6b3199f", "type": "concept", "title": "Conditional mean zero"}, {"id": "49f2a172-8663-4f2d-838c-ced07a48d656", "type": "concept", "title": "Omitted variables"}, {"id": "7fce0478-bbd0-47e0-afe9-9b2fc6ad437e", "type": "concept", "title": "Unobserved heterogeneity"}], "description": "The error term is where omitted causes, randomness, and identification problems enter."}, {"id": "73308bef-f408-469d-a6d0-bb958fd25698", "type": "subtopic", "title": "Linearity and interpretation", "children": [{"id": "e232e5d9-32a6-49c1-96ea-1d7b6dfc4de0", "type": "concept", "title": "Slope coefficients"}, {"id": "07971f18-1fa2-46d2-a831-1624df35c5a8", "type": "concept", "title": "Units and scaling"}, {"id": "9e9ffdde-8a0b-482f-a8e3-abc6665f6afc", "type": "concept", "title": "Logs and elasticities"}], "description": "Linearity is a modeling choice that makes marginal effects interpretable."}, {"id": "84530ede-086a-45f2-8a4f-d512b1f71a5a", "type": "subtopic", "title": "Assumptions as diagnostics", "children": [{"id": "8f714d70-334b-4325-8904-56d8f2641f25", "type": "concept", "title": "Random sampling"}, {"id": "dbf5c225-1129-4a9a-b5ed-8683fc2cc04e", "type": "concept", "title": "No perfect collinearity"}, {"id": "7a6d160f-432f-4625-b015-070458f7dfc9", "type": "concept", "title": "Finite variance"}], "description": "Assumptions are tools for judging whether estimates answer the question asked."}]}, {"id": "f4e3aed2-7522-40aa-8226-2270ee45f270", "type": "topic", "title": "Ordinary least squares (OLS)", "description": "Teach how OLS estimates regression coefficients and why its geometry, algebra, and intuition matter. Core emphasis: Least squares, fitted values, residuals, normal equations, Gauss-Markov theorem, and goodness of fit.", "children": [{"id": "ddf9775d-5cc3-43a9-8942-adefe338f1ff", "type": "subtopic", "title": "Least-squares criterion", "children": [{"id": "b04eb27d-3e45-4e56-b2cf-e706eacb3c32", "type": "concept", "title": "Residuals"}, {"id": "cfeb0601-0c6d-4317-b23c-1ef60ae3006e", "type": "concept", "title": "Sum of squared residuals"}, {"id": "5d195f96-38b6-459d-ac4c-8f816705b4b8", "type": "concept", "title": "Fitted values"}], "description": "OLS chooses coefficients that minimize squared prediction errors."}, {"id": "7d8fdc2d-3770-4095-ba2d-00e66fec7790", "type": "subtopic", "title": "OLS algebra and geometry", "children": [{"id": "b8e7b662-3579-46ad-a26f-19b9b3c26a07", "type": "concept", "title": "Normal equations"}, {"id": "3c45ba6e-731a-407f-b9f9-cacd9a137d88", "type": "concept", "title": "Orthogonality"}, {"id": "57122b90-2cb7-43c0-9b23-d03d0dc3a858", "type": "concept", "title": "Projection interpretation"}], "description": "The normal equations reveal projection logic and orthogonality."}, {"id": "11e79740-a378-4aba-8093-7a74bc807088", "type": "subtopic", "title": "Gauss-Markov theorem", "children": [{"id": "54a6309a-1391-4700-ab1e-3e60e5d3c404", "type": "concept", "title": "Unbiasedness"}, {"id": "839aaa4a-9db0-48aa-aab4-6d331352cc0a", "type": "concept", "title": "Efficiency"}, {"id": "5036c173-0d5b-4083-9eeb-df59f1bfa9df", "type": "concept", "title": "BLUE conditions"}], "description": "Students learn what makes OLS best linear unbiased under specific assumptions."}, {"id": "b718698a-bea6-43ad-89e2-b20a5cd9727c", "type": "subtopic", "title": "Goodness of fit", "children": [{"id": "24e247ed-17e9-44e4-ac04-4a56078790c5", "type": "concept", "title": "R-squared"}, {"id": "396209d6-7aa8-4a94-8402-cc19c2cf5bf3", "type": "concept", "title": "Adjusted R-squared"}, {"id": "9375b981-bb0b-4f9e-96a6-6e96623c7d53", "type": "concept", "title": "Residual standard error"}], "description": "Fit statistics summarize prediction performance but do not prove causality."}]}, {"id": "6998ec6b-a505-45f6-8d52-cfbb3921af3c", "type": "topic", "title": "Inference and hypothesis testing", "description": "Connect estimates to uncertainty, confidence intervals, and evidence-based economic claims. Core emphasis: Sampling distributions, standard errors, t-tests, F-tests, confidence intervals, p-values, and robust inference.", "children": [{"id": "3e1a1bcf-b8aa-4341-b0c3-7d190978843f", "type": "subtopic", "title": "Sampling uncertainty", "children": [{"id": "5ba7a023-bd11-4ebd-a288-15c9af7046bf", "type": "concept", "title": "Estimator distribution"}, {"id": "14e6c83a-2fe8-479a-bde6-9d16112d3459", "type": "concept", "title": "Standard error"}, {"id": "9dcb1e9b-2009-4482-8ad3-02710800f172", "type": "concept", "title": "Degrees of freedom"}], "description": "Estimates vary across samples, so uncertainty must be quantified."}, {"id": "9e0780e8-84fd-4393-a3bd-44cd7726e127", "type": "subtopic", "title": "Single-parameter tests", "children": [{"id": "9e133ad1-8278-4fdc-9fa1-c63a079bfdb2", "type": "concept", "title": "t-statistics"}, {"id": "cf903777-4dfc-4ba6-a061-189e811cca4f", "type": "concept", "title": "p-values"}, {"id": "33bd6d34-739c-4579-9c14-53693d3b4235", "type": "concept", "title": "Confidence intervals"}], "description": "Students learn how to evaluate claims about one coefficient."}, {"id": "1ceb36fd-c393-4cd5-a379-a35b9f26e715", "type": "subtopic", "title": "Joint hypothesis tests", "children": [{"id": "ec8e0e97-58ff-4ce6-ab86-df92fbd4fa35", "type": "concept", "title": "F-tests"}, {"id": "80c95f21-0426-476d-8357-49821c9bbd98", "type": "concept", "title": "Nested models"}, {"id": "2a958694-33a1-45a1-9f59-57ebcaf3c496", "type": "concept", "title": "Linear restrictions"}], "description": "Many economic questions involve restrictions on several coefficients."}, {"id": "c07e82fe-5a9c-4797-9dd4-13e13cb10b4f", "type": "subtopic", "title": "Robust inference", "children": [{"id": "07d66e75-ee73-4a16-9b2a-8a5888701a64", "type": "concept", "title": "Heteroskedasticity-robust SEs"}, {"id": "44e76aa4-46b4-4414-afe8-293198ae2a9c", "type": "concept", "title": "Clustered SEs"}, {"id": "765abe1c-f5e1-40ff-956e-b927afe5e057", "type": "concept", "title": "Small-sample caution"}], "description": "Inference must adapt when classical variance assumptions fail."}]}, {"id": "d416b755-fbea-4b14-b70e-dced8dd283a5", "type": "topic", "title": "Multiple regression", "description": "Show how regression isolates partial relationships by controlling for other variables. Core emphasis: Control variables, partial effects, omitted variable bias, multicollinearity, functional form, interactions, and dummy variables.", "children": [{"id": "7d8d96ca-6401-46e5-82c9-556888fce7b3", "type": "subtopic", "title": "Control variables", "children": [{"id": "466cdc41-b22a-4695-9832-542c00b4ba08", "type": "concept", "title": "Partial effects"}, {"id": "3d0214e6-15f2-4d05-b1c2-8d7a66bacbe6", "type": "concept", "title": "Holding other variables constant"}, {"id": "c851300d-10be-4b81-a7ab-a02c535e448a", "type": "concept", "title": "Bad controls"}], "description": "Controls help compare observations that differ less on confounders."}, {"id": "0629c5b5-4484-4e3b-a948-7eb9bc4fcfce", "type": "subtopic", "title": "Omitted variable bias", "children": [{"id": "31c008ae-1687-4892-8823-8c7cfe022cb2", "type": "concept", "title": "Bias formula intuition"}, {"id": "00a42843-9cc3-4649-85d6-2f00ad207e1a", "type": "concept", "title": "Confounders"}, {"id": "89b33da1-7a1e-432b-b331-7fd1bcf79fca", "type": "concept", "title": "Direction of bias"}], "description": "Bias arises when excluded causes are correlated with included regressors."}, {"id": "a264acd6-b63f-4372-bf35-d20ff50d0b6d", "type": "subtopic", "title": "Functional form", "children": [{"id": "964485ef-5dd0-4f61-9a6e-2ea0befa8ad7", "type": "concept", "title": "Quadratics"}, {"id": "70409202-eb4f-4ade-93dd-a8176008283a", "type": "concept", "title": "Log-linear models"}, {"id": "2d6baea1-cef1-4d01-aa4f-20c881bf16c9", "type": "concept", "title": "Interactions"}], "description": "Model specification changes what coefficients mean."}, {"id": "3e755249-b671-4f83-bbab-84be5f82e4da", "type": "subtopic", "title": "Categorical variables", "children": [{"id": "a7d4538b-db7b-4dc0-9d03-bdb1d268c499", "type": "concept", "title": "Reference categories"}, {"id": "4979d1fb-b68b-49dd-9aaf-954483cd086d", "type": "concept", "title": "Group fixed effects intuition"}, {"id": "240cbf75-b4fd-46b9-a65b-57edea18aad0", "type": "concept", "title": "Interpreting dummy coefficients"}], "description": "Dummy variables let qualitative groups enter regression."}]}, {"id": "f8e6ee06-eef7-4979-8069-78914ad1e954", "type": "topic", "title": "Heteroskedasticity", "description": "Diagnose and handle nonconstant error variance common in real economic data. Core emphasis: Heteroskedasticity, robust standard errors, weighted least squares, diagnostics, and implications for inference.", "children": [{"id": "34a94ae3-1895-4184-9208-920e37a527b4", "type": "subtopic", "title": "What heteroskedasticity means", "children": [{"id": "ac8f21e5-4afc-4b6c-a825-f96ed15110bd", "type": "concept", "title": "Conditional variance"}, {"id": "851d5434-fa00-4678-bea2-05554fea2a39", "type": "concept", "title": "Scale effects"}, {"id": "fb1f36eb-64f5-4769-b1f8-0d61ef0ed595", "type": "concept", "title": "Cross-sectional data examples"}], "description": "Error variance often changes with income, firm size, geography, or other covariates."}, {"id": "2b23bd32-c51c-49e0-ba0a-603b83ff6f93", "type": "subtopic", "title": "Consequences", "children": [{"id": "3e4111ad-26aa-4623-afa7-ff755ebd11dd", "type": "concept", "title": "Unbiasedness versus efficiency"}, {"id": "9cf4e15d-2331-46bf-94e0-2682662dc928", "type": "concept", "title": "Invalid t-tests"}, {"id": "02aab43a-4e71-4720-8922-a26a10c5e6b1", "type": "concept", "title": "Confidence interval distortion"}], "description": "OLS coefficients may remain unbiased while conventional standard errors fail."}, {"id": "77cf717d-31b8-4d8e-847a-05d5f6e8e13c", "type": "subtopic", "title": "Robust standard errors", "children": [{"id": "238b873c-931b-42da-a4d3-6c1833974fa3", "type": "concept", "title": "HC estimators"}, {"id": "d6f2ebfa-e852-4b5d-8851-ffcbf1801101", "type": "concept", "title": "Clustered contexts"}, {"id": "fcb7a4c6-df8f-40d7-9cd3-9827920909ef", "type": "concept", "title": "Reporting conventions"}], "description": "Robust inference is a default habit in applied econometrics."}, {"id": "f0a20206-fa96-4f76-b1b4-a999a1e18b17", "type": "subtopic", "title": "Weighted least squares", "children": [{"id": "4422a594-df7c-402e-9dcd-1f3e94dfcd3c", "type": "concept", "title": "Known variance weights"}, {"id": "ff575204-9e05-4bec-b902-e0f6d10f114c", "type": "concept", "title": "Feasible GLS intuition"}, {"id": "c0292739-eed8-449e-90ce-2a7331847134", "type": "concept", "title": "Risks of bad weights"}], "description": "Weighting can improve efficiency when variance structure is understood."}]}, {"id": "c6c86b3e-b115-429e-8734-2466668b8d15", "type": "topic", "title": "Autocorrelation", "description": "Understand serial dependence in errors and why time ordering changes inference. Core emphasis: Serial correlation, Durbin-Watson intuition, Newey-West standard errors, dynamic models, and time-series residuals.", "children": [{"id": "fbd3e171-e426-4933-b9fe-1a8488812c63", "type": "subtopic", "title": "Serial dependence", "children": [{"id": "a5f00ed7-9e63-49a0-924f-fea0ff332861", "type": "concept", "title": "Lagged residuals"}, {"id": "64b8190e-ea3d-46b9-8064-8a3c26a1a14a", "type": "concept", "title": "Persistence"}, {"id": "c4538dc5-c920-44f0-967a-2d8feee5ed6d", "type": "concept", "title": "Time ordering"}], "description": "Errors can be correlated across time, especially in macro and finance data."}, {"id": "5ff8358b-49bc-415c-83c4-2f3f395a9726", "type": "subtopic", "title": "Consequences for inference", "children": [{"id": "79609633-3264-4e53-89bf-9f79cee4f095", "type": "concept", "title": "Inefficient OLS"}, {"id": "f0d9e83c-79e6-4718-a609-ffed122470c0", "type": "concept", "title": "Biased SEs"}, {"id": "a03a4635-ad92-450b-989c-2bb7991cc2c5", "type": "concept", "title": "Spurious precision"}], "description": "Autocorrelation makes naive standard errors too optimistic or misleading."}, {"id": "95713107-5279-42a3-b085-0fe37844e76d", "type": "subtopic", "title": "Robust corrections", "children": [{"id": "045a1d67-81e5-4639-8fc8-55b2804c1728", "type": "concept", "title": "Newey-West SEs"}, {"id": "2d5015cb-0874-4d29-9cb9-07cb59d1c1b1", "type": "concept", "title": "Cluster by time/unit"}, {"id": "ac09bbde-be12-4d97-ab47-fb720062f286", "type": "concept", "title": "Residual diagnostics"}], "description": "Students learn practical approaches before deeper time-series modeling."}, {"id": "29955009-8127-4039-a7a1-bd2db8bbe95f", "type": "subtopic", "title": "Dynamic specification", "children": [{"id": "493ee51d-08e2-43cf-9748-0e7ab2950a5d", "type": "concept", "title": "Lagged dependent variables"}, {"id": "797ace44-fc40-4db8-9d9c-b35c51497f6d", "type": "concept", "title": "Distributed lags"}, {"id": "a614206a-5684-4766-81ea-3f00e9efbf1c", "type": "concept", "title": "Short-run versus long-run effects"}], "description": "Lagged variables can represent economic adjustment over time."}]}, {"id": "8613203d-fa96-46ad-ae31-41b42a6e0b60", "type": "topic", "title": "Instrumental variables", "description": "Introduce IV as a strategy for causal estimation when regressors are endogenous. Core emphasis: Endogeneity, instruments, relevance, exclusion, two-stage least squares, weak instruments, and overidentification.", "children": [{"id": "4a53fdd5-5a9f-4d44-a1f4-3a1800588dac", "type": "subtopic", "title": "Endogeneity problems", "children": [{"id": "eef162bc-c037-40da-9244-da917e4471f3", "type": "concept", "title": "Omitted variables"}, {"id": "67a7436f-832d-42fe-a316-133d4dd80ab8", "type": "concept", "title": "Simultaneity"}, {"id": "4c3262e6-b234-451e-8c49-d1378af48e17", "type": "concept", "title": "Measurement error"}], "description": "IV addresses situations where OLS cannot recover causal effects."}, {"id": "4178e617-67c9-4705-aa22-8c94dc0c5bfa", "type": "subtopic", "title": "Instrument validity", "children": [{"id": "1a50ff0d-724c-4c15-9033-1404adeabe13", "type": "concept", "title": "Relevance"}, {"id": "28ce3b43-10f0-4783-ba23-8cc39d56a040", "type": "concept", "title": "Exclusion restriction"}, {"id": "1beba60d-eabe-4a1b-98bf-583f3c3dccf0", "type": "concept", "title": "Independence"}], "description": "A good instrument must move treatment while affecting the outcome only through treatment."}, {"id": "0c9135fa-0d73-434a-8e1a-8596eb42586b", "type": "subtopic", "title": "Two-stage least squares", "children": [{"id": "60c38e49-f834-486b-96da-d0b8c7f0c932", "type": "concept", "title": "First stage"}, {"id": "0b6f98df-b4de-401e-9f6d-af348d210264", "type": "concept", "title": "Second stage"}, {"id": "ece67353-8da8-42f8-b223-d9a0be4cbf54", "type": "concept", "title": "Local average treatment effect"}], "description": "2SLS operationalizes IV estimation through predicted variation."}, {"id": "e1dd4078-800c-4d4c-ae58-a349baa275de", "type": "subtopic", "title": "IV diagnostics and risks", "children": [{"id": "1cb84389-f3c6-42aa-ab6b-04f2e1a95a78", "type": "concept", "title": "First-stage F-statistic"}, {"id": "a13b5d93-5156-4a81-b956-4a3fa997e5fc", "type": "concept", "title": "Overidentification tests"}, {"id": "b2b4908a-490c-4b8e-bc8a-75c1a4c8cc96", "type": "concept", "title": "Plausibility arguments"}], "description": "Weak or invalid instruments can be worse than no instrument."}]}, {"id": "9cd49cd3-a55e-41a4-8ab4-da4cb1b8a893", "type": "topic", "title": "Panel data methods", "description": "Use repeated observations to control for unobserved heterogeneity and study change over time. Core emphasis: Pooled OLS, fixed effects, random effects, within estimator, clustered errors, event studies, and panel diagnostics.", "children": [{"id": "078c596c-087f-4262-847d-210fca8f4c99", "type": "subtopic", "title": "Panel data structure", "children": [{"id": "97b00a2c-9419-412a-94d9-0d7b215453da", "type": "concept", "title": "Balanced/unbalanced panels"}, {"id": "894bd696-12c6-435a-a875-15037286d2c2", "type": "concept", "title": "Unit and time dimensions"}, {"id": "e70710e5-7493-435c-8acb-f1be15ecb1c6", "type": "concept", "title": "Long versus wide data"}], "description": "Panel data track units over time, enabling richer designs."}, {"id": "853d384f-261e-41e0-b536-bd8b6c37735a", "type": "subtopic", "title": "Fixed effects", "children": [{"id": "050949c6-0714-46dc-aaef-ad0b5cc33d29", "type": "concept", "title": "Unit fixed effects"}, {"id": "38fafaf9-6771-4425-a486-8cfc15924bfe", "type": "concept", "title": "Time fixed effects"}, {"id": "81fad76d-820b-4afc-8310-3c443bc71dcd", "type": "concept", "title": "Within variation"}], "description": "Fixed effects remove time-invariant unobserved differences."}, {"id": "6334e590-5aba-480b-93ce-4345bbaee29f", "type": "subtopic", "title": "Random effects and model choice", "children": [{"id": "a5e974b7-b470-4f1c-a6c2-de2b560ee8e6", "type": "concept", "title": "RE assumptions"}, {"id": "81cd39f6-e82b-49d4-b922-0bab2e4b043a", "type": "concept", "title": "Hausman intuition"}, {"id": "218eea0f-ab2b-4228-9c5b-28c0da46c46f", "type": "concept", "title": "Between variation"}], "description": "Random effects require stronger assumptions but can be efficient."}, {"id": "751bc7ac-ccbd-4db1-838a-55ef96cd56d7", "type": "subtopic", "title": "Panel inference", "children": [{"id": "bb4d0beb-b6ef-4bae-9799-2e2b35568be8", "type": "concept", "title": "Clustered SEs"}, {"id": "7f4db62e-0cdf-44d7-b430-c1b3b116306a", "type": "concept", "title": "Serial correlation within units"}, {"id": "0280a15f-2244-4ba0-9f72-5f884ac78c4d", "type": "concept", "title": "Few-cluster caution"}], "description": "Standard errors must respect repeated observations."}]}, {"id": "86900c4c-510b-4693-bd33-3f4b4dc73afd", "type": "topic", "title": "Limited dependent variable models (logit, probit)", "description": "Model binary, categorical, count, or censored outcomes without pretending all outcomes are linear and continuous. Core emphasis: Linear probability model, logit, probit, marginal effects, count models, selection, and interpretation.", "children": [{"id": "215d316a-fcc8-484e-964e-239641bff1d2", "type": "subtopic", "title": "Binary outcome basics", "children": [{"id": "ace89bc4-e141-4a62-b2e9-80621486508a", "type": "concept", "title": "Linear probability model"}, {"id": "22e55da1-fb9f-466d-90a7-f0ebb4230e3c", "type": "concept", "title": "Predicted probabilities"}, {"id": "95d21c80-b971-4fff-8a26-09ff78ba0bd4", "type": "concept", "title": "Limitations"}], "description": "Many economic outcomes are yes/no decisions."}, {"id": "dbbe488b-080c-4c3f-9dff-198dfbaeaca6", "type": "subtopic", "title": "Logit and probit", "children": [{"id": "02aa6fce-d297-4f62-a851-02e26f24bb99", "type": "concept", "title": "Latent index"}, {"id": "668b6d5f-e5a3-4f96-b48a-6eda766424e3", "type": "concept", "title": "Maximum likelihood"}, {"id": "604515a8-fec5-478b-94b8-e1e4c2019fd9", "type": "concept", "title": "Link functions"}], "description": "Nonlinear models keep predicted probabilities bounded."}, {"id": "f5a47a07-1e18-4b5e-b2bb-5e633d5b8a89", "type": "subtopic", "title": "Marginal effects", "children": [{"id": "3c32bb58-c8db-4d53-a11e-f6a437b24d60", "type": "concept", "title": "Average marginal effects"}, {"id": "7f762310-424f-4b64-b4de-5780c84f9afe", "type": "concept", "title": "Discrete changes"}, {"id": "ef14f6ed-6ac3-4a54-bb6d-116b18f904cf", "type": "concept", "title": "Baseline dependence"}], "description": "Coefficients need translation into changes in probability."}, {"id": "1b454f58-4876-446a-b3eb-7c392906b7df", "type": "subtopic", "title": "Extensions", "children": [{"id": "b8045d7d-b1ed-4f8d-939f-1ef729fdee97", "type": "concept", "title": "Poisson models"}, {"id": "e6c26805-9405-4db2-97b1-3738ba1832da", "type": "concept", "title": "Tobit intuition"}, {"id": "98f45bcc-19f8-4c65-8e39-b9d3d64a0dc4", "type": "concept", "title": "Sample selection overview"}], "description": "Applied work often faces counts, censoring, or selection."}]}, {"id": "97321491-e768-46a8-9043-4a7c93148f9b", "type": "topic", "title": "Time series econometrics", "description": "Analyze economic variables observed over time while respecting trends, persistence, and forecasting goals. Core emphasis: Stationarity, unit roots, ARIMA, VAR, cointegration, forecasting, structural breaks, and volatility.", "children": [{"id": "4abf5497-a821-40e2-9db6-1d513e370a25", "type": "subtopic", "title": "Stationarity and trends", "children": [{"id": "e7463adf-c122-46d6-9f2a-71bb38fbc429", "type": "concept", "title": "Stationarity"}, {"id": "8a74ead5-1a07-44a7-bc76-ede60e3cf4f7", "type": "concept", "title": "Unit roots"}, {"id": "b8b95aa6-ff08-4be5-8946-9f03555aa964", "type": "concept", "title": "Differencing"}], "description": "Students learn why trending series can produce spurious results."}, {"id": "38816c4d-1699-4194-8933-4b173b72ec1b", "type": "subtopic", "title": "Univariate models", "children": [{"id": "48a14165-bad9-4d93-9285-4fdde49d4692", "type": "concept", "title": "Autoregression"}, {"id": "e91e393a-e537-478d-a488-eeef88525739", "type": "concept", "title": "Moving average terms"}, {"id": "5e182df6-6077-4cb6-bc96-f6059dd7305a", "type": "concept", "title": "Forecast evaluation"}], "description": "ARMA/ARIMA models capture persistence and forecast individual series."}, {"id": "603fa70a-4af0-4a3f-99d3-7fb13bd6fd10", "type": "subtopic", "title": "Multivariate time series", "children": [{"id": "757f40c3-be18-458b-befd-712bc6e2b1a3", "type": "concept", "title": "VAR models"}, {"id": "9bdbc744-ac15-4de5-99fd-af8ddf76613f", "type": "concept", "title": "Impulse responses"}, {"id": "6fc4bf17-b3b0-4bb1-9c01-4c16e9c40e19", "type": "concept", "title": "Granger causality caution"}], "description": "Economic variables often interact dynamically."}, {"id": "381ce606-0cec-472f-9596-4f123dde3ef0", "type": "subtopic", "title": "Long-run relationships", "children": [{"id": "94877e64-88fa-4f15-b757-6b133c5e6edf", "type": "concept", "title": "Error correction"}, {"id": "03cd2600-4c27-4b24-a6ae-974dee13a2d6", "type": "concept", "title": "Common trends"}, {"id": "786a496d-86e1-4749-bf10-d278224dde09", "type": "concept", "title": "Structural breaks"}], "description": "Cointegration handles variables that move together over time."}]}, {"id": "bbb71e07-2b6b-4073-a147-09f6712c5927", "type": "topic", "title": "Modern causal inference: difference-in-differences, regression discontinuity, and experiments", "description": "Frame econometrics around credible research designs for causal questions. Core emphasis: Potential outcomes, randomized experiments, DID, event studies, RD, matching, synthetic control, and threats to identification.", "children": [{"id": "7e33117a-53a9-476a-9292-da58d2c3c3df", "type": "subtopic", "title": "Potential outcomes framework", "children": [{"id": "387f9227-5be3-4bbc-8a12-83fe778d8720", "type": "concept", "title": "Treatment effects"}, {"id": "eeedc49d-2a83-45a2-a298-c857106fdd9a", "type": "concept", "title": "Missing counterfactual"}, {"id": "b98ec8f3-b70e-4a8e-9637-96921a11cc88", "type": "concept", "title": "SUTVA intuition"}], "description": "Causal inference starts by defining counterfactual outcomes."}, {"id": "18c3aa60-c56e-41bf-9080-6e41f604812c", "type": "subtopic", "title": "Randomized experiments", "children": [{"id": "dfc996b0-cb04-4318-b8d4-89e99fac129e", "type": "concept", "title": "RCTs"}, {"id": "33c017fd-fb95-4906-85c1-23471070b9e8", "type": "concept", "title": "Balance"}, {"id": "2325069d-2c69-417a-8045-04b6d919e0cc", "type": "concept", "title": "Compliance and attrition"}], "description": "Randomization creates credible comparison groups when implemented well."}, {"id": "eb0d69ae-7525-4a73-9a2d-00db62d87264", "type": "subtopic", "title": "Difference-in-differences", "children": [{"id": "f53cb70d-033a-40d8-a3d5-d6b732bd296f", "type": "concept", "title": "Parallel trends"}, {"id": "c42f880d-ba13-437a-b198-128d2c3675cc", "type": "concept", "title": "Event studies"}, {"id": "bfdeb4c5-0c65-45dd-a2b0-c7f8257c1d11", "type": "concept", "title": "Staggered adoption caution"}], "description": "DID uses policy timing and comparison groups to estimate effects."}, {"id": "7c4753fa-97f9-46f3-b7ae-a65c52a3f308", "type": "subtopic", "title": "Regression discontinuity", "children": [{"id": "ee676e84-6940-4389-85a3-504bb2432fc0", "type": "concept", "title": "Running variable"}, {"id": "a41ee53a-de8a-4ac1-9613-33d938b76d77", "type": "concept", "title": "Bandwidth"}, {"id": "6712e19d-d9c2-440b-8e89-f45332b78ac7", "type": "concept", "title": "Continuity assumption"}], "description": "RD uses assignment cutoffs to identify local causal effects."}]}, {"id": "7f3583de-b808-4776-bd01-d704b8ae6c76", "type": "topic", "title": "Prediction, machine learning, and model validation", "description": "Add modern predictive tools while keeping the distinction between prediction and causal identification clear. Core emphasis: Train/test splits, cross-validation, regularization, trees, prediction metrics, overfitting, and causal versus predictive goals.", "children": [{"id": "060b0fb6-c4c2-441d-82a6-9314e6b005b0", "type": "subtopic", "title": "Prediction versus causality", "children": [{"id": "0485a451-cbcb-442f-930e-21b6fe051232", "type": "concept", "title": "Target prediction"}, {"id": "fd6670ff-58ee-44e9-a46a-cf60f2c55c84", "type": "concept", "title": "Treatment effect estimation"}, {"id": "9e2941dd-9955-47a2-b7e2-ab63e4d00f0a", "type": "concept", "title": "Confounding"}], "description": "A good predictor is not automatically a causal model."}, {"id": "33aa5652-b88b-4413-988d-8961a15c3fec", "type": "subtopic", "title": "Model validation", "children": [{"id": "4e589bed-5024-4e0a-a39d-c98c66112b61", "type": "concept", "title": "Train/test splits"}, {"id": "bf109227-db25-48f4-bfd6-80d31653442c", "type": "concept", "title": "Cross-validation"}, {"id": "75719982-4af5-41bf-9007-c3aa9632a57d", "type": "concept", "title": "Overfitting"}], "description": "Out-of-sample performance reveals whether models generalize."}, {"id": "cff3ac7b-c4b2-4091-9e89-e9893851143a", "type": "subtopic", "title": "Regularization", "children": [{"id": "333c7fb2-20cf-4a5b-9f7e-f2adcefaed0c", "type": "concept", "title": "Lasso"}, {"id": "573484c7-9998-4b7c-8bec-6b42e10828cb", "type": "concept", "title": "Ridge"}, {"id": "908001c4-b9dd-4cd4-9313-96e78301f64a", "type": "concept", "title": "Bias-variance tradeoff"}], "description": "Regularization improves prediction and variable selection in high-dimensional settings."}, {"id": "b5029fc5-ecd5-4ab8-8674-b2cf54c44e55", "type": "subtopic", "title": "Applied ML tools", "children": [{"id": "b1470029-50c7-4f38-a4dc-ba6906d90c99", "type": "concept", "title": "Trees and forests"}, {"id": "d77eaa00-e6ce-43c7-a6f7-ef88d5c94c01", "type": "concept", "title": "Prediction metrics"}, {"id": "e7f88ded-ce20-4258-b8d1-661d4a3dcfdb", "type": "concept", "title": "Interpretability limits"}], "description": "Students see how modern tools complement econometrics."}]}, {"id": "989aab22-733e-410c-b3ae-84f495153002", "type": "topic", "title": "Reproducible empirical workflow and research communication", "description": "Make students capable of producing transparent, auditable empirical work rather than isolated regressions. Core emphasis: Data acquisition, cleaning, code organization, replication, tables, figures, robustness, ethics, and empirical writing.", "children": [{"id": "a5e59b42-cc72-480d-992c-8a0e3e7ddd1f", "type": "subtopic", "title": "Data sources and cleaning", "children": [{"id": "68db276a-de36-43c8-9969-e5207f636c29", "type": "concept", "title": "IPUMS/FRED/World Bank data"}, {"id": "848d0b97-20a7-4004-b964-fc46fdf1894c", "type": "concept", "title": "Missing data"}, {"id": "a861d76e-3385-43e0-b653-2010ecb0f0ab", "type": "concept", "title": "Codebooks"}], "description": "Empirical credibility begins before estimation."}, {"id": "77a9eabf-86c8-42b9-99ea-1b1b25f4cfcc", "type": "subtopic", "title": "Reproducible code", "children": [{"id": "5929e1cf-f8a1-4c3d-a70b-ce9a03528ce0", "type": "concept", "title": "R/Stata/Python scripts"}, {"id": "09509bcd-5cfb-4145-986a-488f0960e9fc", "type": "concept", "title": "Version control intuition"}, {"id": "57593258-1e8e-4cb9-8110-261532168499", "type": "concept", "title": "Project folders"}], "description": "Analyses should be rerunnable and understandable."}, {"id": "202a2924-a46f-47e0-a717-e3ab67a1d160", "type": "subtopic", "title": "Robustness and sensitivity", "children": [{"id": "347ded3f-7b16-4a58-a2ba-fed6828c18c1", "type": "concept", "title": "Alternative specifications"}, {"id": "6d736f6a-1e72-4509-8cab-93d30c7862e1", "type": "concept", "title": "Placebo tests"}, {"id": "fef05e09-574e-44c9-9091-d832a5fdef53", "type": "concept", "title": "Subsample checks"}], "description": "Students learn to pressure-test empirical claims."}, {"id": "9abc32fa-f04d-4120-9cc6-a9c79e2242ff", "type": "subtopic", "title": "Writing empirical results", "children": [{"id": "2a63324e-9665-47e8-939a-3dfe72e3a547", "type": "concept", "title": "Regression tables"}, {"id": "64cdb67c-1a06-4a17-bf58-0928c8d161aa", "type": "concept", "title": "Figures"}, {"id": "fe12de84-f4d6-4a46-9fb5-be1e4d4d11d7", "type": "concept", "title": "Research memo structure"}], "description": "Communication turns analysis into evidence."}]}], "dbBacked": true}$ecmtjson$::jsonb,
